insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c12-reading-check','Która teza najlepiej opisuje akapit 1?','["Rada debatowała nad ograniczeniem ruchu w centrum i analizowała kilka sprzecznych danych.","Zwolennicy wskazali poprawę jakości powietrza, przyznając zarazem, że dostawy mogą być trudniejsze.","Przeciwnicy przedstawili kontrargument dotyczący kosztów, lecz pojedynczy przykład nie przesądzał wyniku."]',0,'Первый вариант точно передаёт содержание абзаца.',1,true);
