insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c13-reading-check','Która teza najlepiej opisuje akapit 1?','["Studentka porównała dwa komentarze o tej samej zmianie w mieście.","Pierwszy tekst pozornie neutralnie wyliczał koszty, lecz pomijał korzyści i głosy mieszkańców.","Drugi używał ironicznych pytań, dlatego jego wydźwięk był wyraźnie wartościujący."]',0,'Первый вариант точно передаёт содержание абзаца.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c14-grammar','Wybierz wyrażenie pasujące do celu: неспециалист.','["odbiorca niespecjalistyczny","przełożyć na prosty język","uniknąć uproszczenia"]',0,'odbiorca niespecjalistyczny oznacza: неспециалист.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c14-quiz','Co znaczy „odbiorca niespecjalistyczny”?','["неспециалист","переложить простым языком","избежать упрощения"]',0,'„odbiorca niespecjalistyczny” — неспециалист.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c14-reading-check','Która teza najlepiej opisuje akapit 1?','["Analityczka miała wyjaśnić mieszkańcom raport o retencji wody, pełen terminów technicznych.","Najpierw wydobyła sedno: więcej zieleni spowalnia odpływ i zmniejsza ryzyko lokalnych podtopień.","Podała analogię do gąbki, ale zaznaczyła, że park nie zatrzyma każdej ulewy."]',0,'Первый вариант точно передаёт содержание абзаца.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c15-grammar','Wybierz wyrażenie pasujące do celu: проблемный абзац.','["akapit problemowy","zdanie tematyczne","łącznik"]',0,'akapit problemowy oznacza: проблемный абзац.',1,true);
