insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c15-reading-check','Która teza najlepiej opisuje akapit 1?','["Marta redagowała esej o pracy zdalnej, opierając się na trzech badaniach o różnych metodach.","W zdaniu tematycznym każdego akapitu nazywała problem, a następnie zestawiała zgodne i sprzeczne wyniki.","Nie streszczała źródeł osobno: budowała syntezę, wskazywała ograniczenia prób i doprecyzowała własną tezę."]',0,'Первый вариант точно передаёт содержание абзаца.',1,true);
