insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c16-reading-check','Która teza najlepiej opisuje akapit 1?','["Ekspertka przedstawiła zarządowi plan migracji systemu, zaczynając od warunków brzegowych i zakresu odpowiedzialności.","Zamiast obiecywać bezproblemowy termin oszacowała nakład oraz trzy ryzyka operacyjne wraz z prawdopodobieństwem.","Działy miały rozbieżne oczekiwania, więc uzgodniła mierzalne kryteria i wyraźny punkt decyzyjny."]',0,'Первый вариант точно передаёт содержание абзаца.',1,true);
