insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c17-reading-check','Która teza najlepiej opisuje akapit 1?','["W opowiadaniu fikcyjnej autorki narrator opisuje pusty dworzec, lecz stopniowo ujawnia własny udział w wydarzeniach.","Krótkie zdania przyspieszają rytm przed przyjazdem pociągu, a rozbudowane metafory zatrzymują czas we wspomnieniach.","Powracający obraz zegara można odczytać jako znak winy, choć tekst nie przesądza jednej interpretacji."]',0,'Первый вариант точно передаёт содержание абзаца.',1,true);
