insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c14-reading-check','Która teza najlepiej opisuje akapit 3?','["Podała analogię do gąbki, ale zaznaczyła, że park nie zatrzyma każdej ulewy.","Pominęła wzory, zachowała natomiast liczby potrzebne do porównania wariantów i objaśniła ich zależność.","Na końcu poprosiła odbiorców o własne podsumowanie, aby sprawdzić zrozumienie bez infantylizowania rozmowy."]',0,'Первый вариант точно передаёт содержание абзаца.',3,true);
