insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c16-reading-check','Która teza najlepiej opisuje akapit 3?','["Działy miały rozbieżne oczekiwania, więc uzgodniła mierzalne kryteria i wyraźny punkt decyzyjny.","Negocjacje dotyczyły nie celu, lecz kolejności etapów, poufności danych i wariantu awaryjnego.","Rekomendacja była stanowcza, ale wskazywała granice ekspertyzy oraz osobę ponoszącą odpowiedzialność końcową."]',0,'Первый вариант точно передаёт содержание абзаца.',3,true);
