insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c11-reading-check','Która teza najlepiej opisuje akapit 5?','["Dobry rejestr nie polega na trudnych słowach, tylko na świadomym dopasowaniu tonu do adresata.","Redaktorka przygotowała trzy wersje tej samej wiadomości: do przyjaciela, zespołu i urzędu.","Wersja potoczna była krótka i bezpośrednia, lecz w urzędzie brzmiałaby niestosownie."]',0,'Первый вариант точно передаёт содержание абзаца.',5,true);
