insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c12-reading-check','Która teza najlepiej opisuje akapit 5?','["Wniosek poparł pilotaż o tyle, o ile miasto równolegle zbada dostępność i skutki dla handlu.","Rada debatowała nad ograniczeniem ruchu w centrum i analizowała kilka sprzecznych danych.","Zwolennicy wskazali poprawę jakości powietrza, przyznając zarazem, że dostawy mogą być trudniejsze."]',0,'Первый вариант точно передаёт содержание абзаца.',5,true);
