insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c13-reading-check','Która teza najlepiej opisuje akapit 5?','["Uznała, że analityczne czytanie oddziela treść jawną od wniosku sugerowanego przez strukturę tekstu.","Studentka porównała dwa komentarze o tej samej zmianie w mieście.","Pierwszy tekst pozornie neutralnie wyliczał koszty, lecz pomijał korzyści i głosy mieszkańców."]',0,'Первый вариант точно передаёт содержание абзаца.',5,true);
