insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c14-reading-check','Która teza najlepiej opisuje akapit 5?','["Na końcu poprosiła odbiorców o własne podsumowanie, aby sprawdzić zrozumienie bez infantylizowania rozmowy.","Analityczka miała wyjaśnić mieszkańcom raport o retencji wody, pełen terminów technicznych.","Najpierw wydobyła sedno: więcej zieleni spowalnia odpływ i zmniejsza ryzyko lokalnych podtopień."]',0,'Первый вариант точно передаёт содержание абзаца.',5,true);
