insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c18-reading-check','Która teza najlepiej opisuje akapit 5?','["Decyzję odroczono do konsultacji, ale ustalono warunki konieczne pilotażu i sposób oceny kompromisu.","Mieszkańcy debatowali o przebudowie placu, a moderatorka najpierw nazwała interesariuszy i ramy rozmowy.","Oś sporu dotyczyła miejsc parkingowych, jednak obie strony uznawały bezpieczeństwo pieszych za obszar zgody."]',0,'Первый вариант точно передаёт содержание абзаца.',5,true);
