insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c11-tekst','c1-style-register','Стиль и регистр','Адаптируем речь к аудитории и ситуации','C1',14,'🎭','["Redaktorka przygotowała trzy wersje tej samej wiadomości: do przyjaciela, zespołu i urzędu.","Wersja potoczna była krótka i bezpośrednia, lecz w urzędzie brzmiałaby niestosownie.","Tekst oficjalny zawierał zwrot grzecznościowy i precyzyjny cel, ale nie był chłodny.","Redaktorka zauważyła, że nadmierna uprzejmość może brzmieć protekcjonalnie.","Dobry rejestr nie polega na trudnych słowach, tylko na świadomym dopasowaniu tonu do adresata."]','{"rejestr":{"lemma":"rejestr","translation":"регистр","part_of_speech":"wyrażenie"},"dobór słów":{"lemma":"dobór słów","translation":"выбор слов","part_of_speech":"wyrażenie"},"zwrot grzecznościowy":{"lemma":"zwrot grzecznościowy","translation":"формула вежливости","part_of_speech":"wyrażenie"},"potoczny":{"lemma":"potoczny","translation":"разговорный","part_of_speech":"wyrażenie"},"neutralny":{"lemma":"neutralny","translation":"нейтральный","part_of_speech":"wyrażenie"},"oficjalny":{"lemma":"oficjalny","translation":"официальный","part_of_speech":"wyrażenie"},"dostosować wypowiedź":{"lemma":"dostosować wypowiedź","translation":"адаптировать высказывание","part_of_speech":"wyrażenie"},"zachować dystans":{"lemma":"zachować dystans","translation":"сохранять дистанцию","part_of_speech":"wyrażenie"},"skrócić dystans":{"lemma":"skrócić dystans","translation":"сократить дистанцию","part_of_speech":"wyrażenie"},"brzmieć protekcjonalnie":{"lemma":"brzmieć protekcjonalnie","translation":"звучать покровительственно","part_of_speech":"wyrażenie"},"niestosowny":{"lemma":"niestosowny","translation":"неуместный","part_of_speech":"wyrażenie"},"adresat":{"lemma":"adresat","translation":"адресат","part_of_speech":"wyrażenie"},"kontekst sytuacyjny":{"lemma":"kontekst sytuacyjny","translation":"ситуативный контекст","part_of_speech":"wyrażenie"},"przeredagować":{"lemma":"przeredagować","translation":"переформулировать","part_of_speech":"wyrażenie"},"wyważyć ton":{"lemma":"wyważyć ton","translation":"выверить тон","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c11-reading-check"}',47,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c12-tekst','c1-complex-argument','Сложная аргументация','Строим позицию с оговорками и контраргументом','C1',14,'⚖️','["Rada debatowała nad ograniczeniem ruchu w centrum i analizowała kilka sprzecznych danych.","Zwolennicy wskazali poprawę jakości powietrza, przyznając zarazem, że dostawy mogą być trudniejsze.","Przeciwnicy przedstawili kontrargument dotyczący kosztów, lecz pojedynczy przykład nie przesądzał wyniku.","Ekspert zważył argumenty i oddzielił przesłanki od założeń, których raport nie potwierdzał.","Wniosek poparł pilotaż o tyle, o ile miasto równolegle zbada dostępność i skutki dla handlu."]','{"zastrzeżenie":{"lemma":"zastrzeżenie","translation":"оговорка","part_of_speech":"wyrażenie"},"przesłanka":{"lemma":"przesłanka","translation":"предпосылка","part_of_speech":"wyrażenie"},"tok rozumowania":{"lemma":"tok rozumowania","translation":"ход рассуждения","part_of_speech":"wyrażenie"},"kontrargument":{"lemma":"kontrargument","translation":"контраргумент","part_of_speech":"wyrażenie"},"obalić zarzut":{"lemma":"obalić zarzut","translation":"опровергнуть возражение","part_of_speech":"wyrażenie"},"przyznać rację":{"lemma":"przyznać rację","translation":"признать правоту","part_of_speech":"wyrażenie"},"z dużym prawdopodobieństwem":{"lemma":"z dużym prawdopodobieństwem","translation":"с большой вероятностью","part_of_speech":"wyrażenie"},"nie przesądza":{"lemma":"nie przesądza","translation":"не предрешает","part_of_speech":"wyrażenie"},"o tyle, o ile":{"lemma":"o tyle, o ile","translation":"постольку, поскольку","part_of_speech":"wyrażenie"},"tym niemniej":{"lemma":"tym niemniej","translation":"тем не менее","part_of_speech":"wyrażenie"},"wynikać pośrednio":{"lemma":"wynikać pośrednio","translation":"косвенно следовать","part_of_speech":"wyrażenie"},"uprawniony wniosek":{"lemma":"uprawniony wniosek","translation":"обоснованный вывод","part_of_speech":"wyrażenie"},"nadużycie":{"lemma":"nadużycie","translation":"злоупотребление","part_of_speech":"wyrażenie"},"ważyć argumenty":{"lemma":"ważyć argumenty","translation":"взвешивать аргументы","part_of_speech":"wyrażenie"},"niuansować stanowisko":{"lemma":"niuansować stanowisko","translation":"нюансировать позицию","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c12-reading-check"}',48,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c13-tekst','c1-analytical-reading','Аналитическое чтение','Выявляем предпосылки, тон и стратегию автора','C1',14,'🔎','["Studentka porównała dwa komentarze o tej samej zmianie w mieście.","Pierwszy tekst pozornie neutralnie wyliczał koszty, lecz pomijał korzyści i głosy mieszkańców.","Drugi używał ironicznych pytań, dlatego jego wydźwięk był wyraźnie wartościujący.","Studentka zbadała dobór przykładów, źródła i ramę interpretacyjną zamiast zgadywać poglądy autora.","Uznała, że analityczne czytanie oddziela treść jawną od wniosku sugerowanego przez strukturę tekstu."]','{"założenie ukryte":{"lemma":"założenie ukryte","translation":"скрытая предпосылка","part_of_speech":"wyrażenie"},"rama interpretacyjna":{"lemma":"rama interpretacyjna","translation":"интерпретационная рамка","part_of_speech":"wyrażenie"},"dobór przykładów":{"lemma":"dobór przykładów","translation":"подбор примеров","part_of_speech":"wyrażenie"},"pominięcie":{"lemma":"pominięcie","translation":"умолчание","part_of_speech":"wyrażenie"},"wydźwięk":{"lemma":"wydźwięk","translation":"оттенок, звучание","part_of_speech":"wyrażenie"},"ironiczny":{"lemma":"ironiczny","translation":"ироничный","part_of_speech":"wyrażenie"},"wartościujący":{"lemma":"wartościujący","translation":"оценочный","part_of_speech":"wyrażenie"},"pozornie neutralny":{"lemma":"pozornie neutralny","translation":"внешне нейтральный","part_of_speech":"wyrażenie"},"sugerować":{"lemma":"sugerować","translation":"намекать","part_of_speech":"wyrażenie"},"podważać":{"lemma":"podważać","translation":"ставить под сомнение","part_of_speech":"wyrażenie"},"strategia autora":{"lemma":"strategia autora","translation":"стратегия автора","part_of_speech":"wyrażenie"},"wiarygodność":{"lemma":"wiarygodność","translation":"достоверность","part_of_speech":"wyrażenie"},"punkt widzenia":{"lemma":"punkt widzenia","translation":"точка зрения","part_of_speech":"wyrażenie"},"odczytać intencję":{"lemma":"odczytać intencję","translation":"считать намерение","part_of_speech":"wyrażenie"},"wniosek implicytny":{"lemma":"wniosek implicytny","translation":"имплицитный вывод","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c13-reading-check"}',49,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c14-tekst','c1-mediation','Медиация','Передаём сложную информацию неспециалисту','C1',14,'🧩','["Analityczka miała wyjaśnić mieszkańcom raport o retencji wody, pełen terminów technicznych.","Najpierw wydobyła sedno: więcej zieleni spowalnia odpływ i zmniejsza ryzyko lokalnych podtopień.","Podała analogię do gąbki, ale zaznaczyła, że park nie zatrzyma każdej ulewy.","Pominęła wzory, zachowała natomiast liczby potrzebne do porównania wariantów i objaśniła ich zależność.","Na końcu poprosiła odbiorców o własne podsumowanie, aby sprawdzić zrozumienie bez infantylizowania rozmowy."]','{"sedno":{"lemma":"sedno","translation":"суть","part_of_speech":"wyrażenie"},"odbiorca niespecjalistyczny":{"lemma":"odbiorca niespecjalistyczny","translation":"неспециалист","part_of_speech":"wyrażenie"},"przełożyć na prosty język":{"lemma":"przełożyć na prosty język","translation":"переложить простым языком","part_of_speech":"wyrażenie"},"uniknąć uproszczenia":{"lemma":"uniknąć uproszczenia","translation":"избежать упрощения","part_of_speech":"wyrażenie"},"objaśnić pojęcie":{"lemma":"objaśnić pojęcie","translation":"объяснить понятие","part_of_speech":"wyrażenie"},"zachować zastrzeżenie":{"lemma":"zachować zastrzeżenie","translation":"сохранить оговорку","part_of_speech":"wyrażenie"},"uporządkować informacje":{"lemma":"uporządkować informacje","translation":"структурировать информацию","part_of_speech":"wyrażenie"},"podać analogię":{"lemma":"podać analogię","translation":"привести аналогию","part_of_speech":"wyrażenie"},"wyjaśnić zależność":{"lemma":"wyjaśnić zależność","translation":"объяснить зависимость","part_of_speech":"wyrażenie"},"pominąć detal":{"lemma":"pominąć detal","translation":"опустить деталь","part_of_speech":"wyrażenie"},"sprawdzić zrozumienie":{"lemma":"sprawdzić zrozumienie","translation":"проверить понимание","part_of_speech":"wyrażenie"},"podsumować":{"lemma":"podsumować","translation":"подвести итог","part_of_speech":"wyrażenie"},"pośredniczyć":{"lemma":"pośredniczyć","translation":"посредничать","part_of_speech":"wyrażenie"},"wiernie oddać sens":{"lemma":"wiernie oddać sens","translation":"точно передать смысл","part_of_speech":"wyrażenie"},"stopniować trudność":{"lemma":"stopniować trudność","translation":"дозировать сложность","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c14-reading-check"}',50,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c15-tekst','c1-academic-writing','Академическое письмо','Создаём связный аналитический текст и синтезируем источники','C1',14,'📝','["Marta redagowała esej o pracy zdalnej, opierając się na trzech badaniach o różnych metodach.","W zdaniu tematycznym każdego akapitu nazywała problem, a następnie zestawiała zgodne i sprzeczne wyniki.","Nie streszczała źródeł osobno: budowała syntezę, wskazywała ograniczenia prób i doprecyzowała własną tezę.","Argument poboczny przeniosła do przypisu, ponieważ zakłócał spójność wywodu i hierarchię informacji.","Konkluzja nie powtarzała wstępu, lecz odpowiadała na pytanie i formułowała ostrożny dalszy wniosek."]','{"spójność wywodu":{"lemma":"spójność wywodu","translation":"связность рассуждения","part_of_speech":"wyrażenie"},"akapit problemowy":{"lemma":"akapit problemowy","translation":"проблемный абзац","part_of_speech":"wyrażenie"},"zdanie tematyczne":{"lemma":"zdanie tematyczne","translation":"тематическое предложение","part_of_speech":"wyrażenie"},"łącznik":{"lemma":"łącznik","translation":"средство связи","part_of_speech":"wyrażenie"},"synteza źródeł":{"lemma":"synteza źródeł","translation":"синтез источников","part_of_speech":"wyrażenie"},"przywołać badanie":{"lemma":"przywołać badanie","translation":"сослаться на исследование","part_of_speech":"wyrażenie"},"zastrzec":{"lemma":"zastrzec","translation":"оговорить","part_of_speech":"wyrażenie"},"doprecyzować tezę":{"lemma":"doprecyzować tezę","translation":"уточнить тезис","part_of_speech":"wyrażenie"},"wywód":{"lemma":"wywód","translation":"изложение","part_of_speech":"wyrażenie"},"konkluzja":{"lemma":"konkluzja","translation":"заключение","part_of_speech":"wyrażenie"},"argument poboczny":{"lemma":"argument poboczny","translation":"второстепенный аргумент","part_of_speech":"wyrażenie"},"hierarchia informacji":{"lemma":"hierarchia informacji","translation":"иерархия информации","part_of_speech":"wyrażenie"},"unikać powtórzeń":{"lemma":"unikać powtórzeń","translation":"избегать повторов","part_of_speech":"wyrażenie"},"redagować":{"lemma":"redagować","translation":"редактировать","part_of_speech":"wyrażenie"},"odsyłacz":{"lemma":"odsyłacz","translation":"ссылка","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c15-reading-check"}',51,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c16-tekst','c1-professional-expertise','Профессиональная экспертиза','Объясняем сложную тему и ведём точные переговоры','C1',14,'💼','["Ekspertka przedstawiła zarządowi plan migracji systemu, zaczynając od warunków brzegowych i zakresu odpowiedzialności.","Zamiast obiecywać bezproblemowy termin oszacowała nakład oraz trzy ryzyka operacyjne wraz z prawdopodobieństwem.","Działy miały rozbieżne oczekiwania, więc uzgodniła mierzalne kryteria i wyraźny punkt decyzyjny.","Negocjacje dotyczyły nie celu, lecz kolejności etapów, poufności danych i wariantu awaryjnego.","Rekomendacja była stanowcza, ale wskazywała granice ekspertyzy oraz osobę ponoszącą odpowiedzialność końcową."]','{"zakres odpowiedzialności":{"lemma":"zakres odpowiedzialności","translation":"сфера ответственности","part_of_speech":"wyrażenie"},"warunek brzegowy":{"lemma":"warunek brzegowy","translation":"граничное условие","part_of_speech":"wyrażenie"},"ryzyko operacyjne":{"lemma":"ryzyko operacyjne","translation":"операционный риск","part_of_speech":"wyrażenie"},"wykonalność":{"lemma":"wykonalność","translation":"реализуемость","part_of_speech":"wyrażenie"},"uzgodnić kryteria":{"lemma":"uzgodnić kryteria","translation":"согласовать критерии","part_of_speech":"wyrażenie"},"przedstawić rekomendację":{"lemma":"przedstawić rekomendację","translation":"представить рекомендацию","part_of_speech":"wyrażenie"},"zastrzec poufność":{"lemma":"zastrzec poufność","translation":"оговорить конфиденциальность","part_of_speech":"wyrażenie"},"wariant awaryjny":{"lemma":"wariant awaryjny","translation":"резервный вариант","part_of_speech":"wyrażenie"},"oszacować nakład":{"lemma":"oszacować nakład","translation":"оценить трудозатраты","part_of_speech":"wyrażenie"},"rozbieżność":{"lemma":"rozbieżność","translation":"расхождение","part_of_speech":"wyrażenie"},"wynegocjować":{"lemma":"wynegocjować","translation":"согласовать на переговорах","part_of_speech":"wyrażenie"},"doprowadzić do eskalacji":{"lemma":"doprowadzić do eskalacji","translation":"привести к эскалации","part_of_speech":"wyrażenie"},"punkt decyzyjny":{"lemma":"punkt decyzyjny","translation":"точка принятия решения","part_of_speech":"wyrażenie"},"mierzalny rezultat":{"lemma":"mierzalny rezultat","translation":"измеримый результат","part_of_speech":"wyrażenie"},"odpowiedzialność końcowa":{"lemma":"odpowiedzialność końcowa","translation":"итоговая ответственность","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c16-reading-check"}',52,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c17-tekst','c1-literary-language','Литературный язык','Анализируем голос, образность и синтаксическую вариативность','C1',14,'📚','["W opowiadaniu fikcyjnej autorki narrator opisuje pusty dworzec, lecz stopniowo ujawnia własny udział w wydarzeniach.","Krótkie zdania przyspieszają rytm przed przyjazdem pociągu, a rozbudowane metafory zatrzymują czas we wspomnieniach.","Powracający obraz zegara można odczytać jako znak winy, choć tekst nie przesądza jednej interpretacji.","Czytelnik wie więcej niż bohater, dlatego jego pewne deklaracje tworzą ironię dramatyczną i podważają wiarygodność głosu.","Punkt kulminacyjny pozostaje eliptyczny; niedopowiedzenie zmusza odbiorcę do połączenia perspektyw i oceny narratora."]','{"narrator niewiarygodny":{"lemma":"narrator niewiarygodny","translation":"ненадёжный рассказчик","part_of_speech":"wyrażenie"},"perspektywa":{"lemma":"perspektywa","translation":"перспектива","part_of_speech":"wyrażenie"},"metafora":{"lemma":"metafora","translation":"метафора","part_of_speech":"wyrażenie"},"porównanie":{"lemma":"porównanie","translation":"сравнение","part_of_speech":"wyrażenie"},"rytm zdania":{"lemma":"rytm zdania","translation":"ритм предложения","part_of_speech":"wyrażenie"},"elipsa":{"lemma":"elipsa","translation":"эллипсис","part_of_speech":"wyrażenie"},"niedopowiedzenie":{"lemma":"niedopowiedzenie","translation":"недосказанность","part_of_speech":"wyrażenie"},"ironia dramatyczna":{"lemma":"ironia dramatyczna","translation":"драматическая ирония","part_of_speech":"wyrażenie"},"stylizacja":{"lemma":"stylizacja","translation":"стилизация","part_of_speech":"wyrażenie"},"głos bohatera":{"lemma":"głos bohatera","translation":"голос героя","part_of_speech":"wyrażenie"},"obrazowanie":{"lemma":"obrazowanie","translation":"образность","part_of_speech":"wyrażenie"},"kontrast":{"lemma":"kontrast","translation":"контраст","part_of_speech":"wyrażenie"},"wieloznaczność":{"lemma":"wieloznaczność","translation":"многозначность","part_of_speech":"wyrażenie"},"punkt kulminacyjny":{"lemma":"punkt kulminacyjny","translation":"кульминация","part_of_speech":"wyrażenie"},"interpretacja":{"lemma":"interpretacja","translation":"интерпретация","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c17-reading-check"}',53,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c18-tekst','c1-public-discussion','Общественная дискуссия','Модерируем сложный разговор и ищем область согласия','C1',14,'🏛️','["Mieszkańcy debatowali o przebudowie placu, a moderatorka najpierw nazwała interesariuszy i ramy rozmowy.","Oś sporu dotyczyła miejsc parkingowych, jednak obie strony uznawały bezpieczeństwo pieszych za obszar zgody.","Moderatorka oddała sprawiedliwość argumentowi mniejszości i zatrzymała wypowiedź, która eskalowała konflikt.","Podsumowanie robocze rozdzieliło fakty, wartości i kwestie wymagające danych, dzięki czemu napięcie stało się czytelne.","Decyzję odroczono do konsultacji, ale ustalono warunki konieczne pilotażu i sposób oceny kompromisu."]','{"obszar zgody":{"lemma":"obszar zgody","translation":"область согласия","part_of_speech":"wyrażenie"},"oś sporu":{"lemma":"oś sporu","translation":"ось спора","part_of_speech":"wyrażenie"},"interesariusz":{"lemma":"interesariusz","translation":"заинтересованная сторона","part_of_speech":"wyrażenie"},"legitymizować decyzję":{"lemma":"legitymizować decyzję","translation":"легитимизировать решение","part_of_speech":"wyrażenie"},"zrównoważyć interesy":{"lemma":"zrównoważyć interesy","translation":"сбалансировать интересы","part_of_speech":"wyrażenie"},"oddać sprawiedliwość argumentowi":{"lemma":"oddać sprawiedliwość argumentowi","translation":"отдать должное аргументу","part_of_speech":"wyrażenie"},"nazwać napięcie":{"lemma":"nazwać napięcie","translation":"обозначить напряжение","part_of_speech":"wyrażenie"},"ramy debaty":{"lemma":"ramy debaty","translation":"рамки дискуссии","part_of_speech":"wyrażenie"},"eskalować konflikt":{"lemma":"eskalować konflikt","translation":"обострять конфликт","part_of_speech":"wyrażenie"},"wypracować kompromis":{"lemma":"wypracować kompromis","translation":"выработать компромисс","part_of_speech":"wyrażenie"},"warunek konieczny":{"lemma":"warunek konieczny","translation":"необходимое условие","part_of_speech":"wyrażenie"},"stanowisko mniejszości":{"lemma":"stanowisko mniejszości","translation":"позиция меньшинства","part_of_speech":"wyrażenie"},"podsumowanie robocze":{"lemma":"podsumowanie robocze","translation":"рабочее резюме","part_of_speech":"wyrażenie"},"procedura konsultacji":{"lemma":"procedura konsultacji","translation":"процедура консультаций","part_of_speech":"wyrażenie"},"odroczyć decyzję":{"lemma":"odroczyć decyzję","translation":"отложить решение","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c18-reading-check"}',54,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c19-tekst','c1-media-language','Язык медиа','Сравниваем жанры, редактируем и преобразуем материал','C1',14,'📰','["Redakcja otrzymała depeszę o nowym programie transportowym i przygotowała z niej trzy materiały.","Krótka wiadomość zaczynała się od neutralnego leadu, podczas gdy felieton wyostrzał tezę i oceniał decyzję władz.","Post w mediach społecznościowych wymagał skrótu, lecz redaktorka usunęła nagłówek, który sugerował skutek niepotwierdzony w danych.","W każdym gatunku zachowała liczby, źródło i zastrzeżenia; komentarz został wyraźnie oddzielony od informacji.","Ćwiczenie pokazało, że przekształcenie gatunku zmienia selekcję i ton, ale nie powinno zmieniać sensu faktów."]','{"konwencja gatunkowa":{"lemma":"konwencja gatunkowa","translation":"жанровая конвенция","part_of_speech":"wyrażenie"},"lead":{"lemma":"lead","translation":"лид","part_of_speech":"wyrażenie"},"nagłówek wartościujący":{"lemma":"nagłówek wartościujący","translation":"оценочный заголовок","part_of_speech":"wyrażenie"},"rama przekazu":{"lemma":"rama przekazu","translation":"рамка сообщения","part_of_speech":"wyrażenie"},"depesza":{"lemma":"depesza","translation":"информационное сообщение","part_of_speech":"wyrażenie"},"felieton":{"lemma":"felieton","translation":"фельетон","part_of_speech":"wyrażenie"},"sprostowanie":{"lemma":"sprostowanie","translation":"опровержение, исправление","part_of_speech":"wyrażenie"},"autoryzacja wypowiedzi":{"lemma":"autoryzacja wypowiedzi","translation":"согласование высказывания","part_of_speech":"wyrażenie"},"skrót myślowy":{"lemma":"skrót myślowy","translation":"смысловое сокращение","part_of_speech":"wyrażenie"},"selekcja informacji":{"lemma":"selekcja informacji","translation":"отбор информации","part_of_speech":"wyrażenie"},"przekształcić gatunek":{"lemma":"przekształcić gatunek","translation":"преобразовать жанр","part_of_speech":"wyrażenie"},"zachować sens":{"lemma":"zachować sens","translation":"сохранить смысл","part_of_speech":"wyrażenie"},"wyostrzyć tezę":{"lemma":"wyostrzyć tezę","translation":"заострить тезис","part_of_speech":"wyrażenie"},"oddzielić komentarz":{"lemma":"oddzielić komentarz","translation":"отделить комментарий","part_of_speech":"wyrażenie"},"odpowiedzialność redakcyjna":{"lemma":"odpowiedzialność redakcyjna","translation":"редакционная ответственность","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c19-reading-check"}',55,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c110-tekst','c1-final-project','Проект C1','Интегрируем исследование, письмо, презентацию и медиацию','C1',14,'🏆','["Zespół kończący poziom C1 badał, jak miasto może jasno informować mieszkańców o falach upałów.","Uczestnicy porównali dane, komunikaty urzędu i wywiady, a rozbieżności opisali zamiast ukrywać je w jednej średniej.","Powstały trzy wersje materiału: raport analityczny, krótka informacja publiczna i prezentacja dla osób starszych.","Podczas obrony zespół odpowiedział na zarzut zbyt małej próby, uznał ograniczenie i sformułował wniosek warunkowy.","Samoocena wykazała, że projekt łączył precyzję, mediację i odpowiedzialność za odbiorcę, a dalszym kierunkiem stały się testy z użytkownikami."]','{"zakres projektu":{"lemma":"zakres projektu","translation":"охват проекта","part_of_speech":"wyrażenie"},"pytanie przewodnie":{"lemma":"pytanie przewodnie","translation":"ведущий вопрос","part_of_speech":"wyrażenie"},"triangulacja źródeł":{"lemma":"triangulacja źródeł","translation":"триангуляция источников","part_of_speech":"wyrażenie"},"kryterium oceny":{"lemma":"kryterium oceny","translation":"критерий оценки","part_of_speech":"wyrażenie"},"synteza ustaleń":{"lemma":"synteza ustaleń","translation":"синтез выводов","part_of_speech":"wyrażenie"},"wersja dla odbiorcy":{"lemma":"wersja dla odbiorcy","translation":"версия для аудитории","part_of_speech":"wyrażenie"},"obrona projektu":{"lemma":"obrona projektu","translation":"защита проекта","part_of_speech":"wyrażenie"},"odpowiedzieć na zarzut":{"lemma":"odpowiedzieć na zarzut","translation":"ответить на возражение","part_of_speech":"wyrażenie"},"uznać ograniczenie":{"lemma":"uznać ograniczenie","translation":"признать ограничение","part_of_speech":"wyrażenie"},"wniosek warunkowy":{"lemma":"wniosek warunkowy","translation":"условный вывод","part_of_speech":"wyrażenie"},"materiał pomocniczy":{"lemma":"materiał pomocniczy","translation":"вспомогательный материал","part_of_speech":"wyrażenie"},"próba generalna":{"lemma":"próba generalna","translation":"генеральная репетиция","part_of_speech":"wyrażenie"},"informacja zwrotna":{"lemma":"informacja zwrotna","translation":"обратная связь","part_of_speech":"wyrażenie"},"samoocena":{"lemma":"samoocena","translation":"самооценка","part_of_speech":"wyrażenie"},"dalszy kierunek":{"lemma":"dalszy kierunek","translation":"дальнейшее направление","part_of_speech":"wyrażenie"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"c110-reading-check"}',56,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
